<section class="admin-content"><div class="admin-heading"><div><div class="eyebrow">مرکز کنترل پلتفرم</div><h1><?= e($title) ?></h1><p class="muted"><?= e($description) ?></p></div><a class="button" href="<?= url('/admin') ?>">بازگشت به داشبورد</a></div><div class="admin-panel"><div class="filter-links"><a href="<?= url('/admin/'.$table) ?>">همه</a><a href="<?= url('/admin/'.$table.'?limit=25') ?>">آخرین موارد</a></div><div class="table-wrap"><table><thead><tr><?php foreach ($columns as $column): ?><th><?= e(ucwords(str_replace('_',' ', $column))) ?></th><?php endforeach; ?><th>عملیات</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><?php foreach ($columns as $column): ?><td><?= e((string)($row[$column] ?? '—')) ?></td><?php endforeach; ?><td><?php if(in_array($table,['jobs','posts','reports'],true)): ?><form method="post" action="<?=url('/admin/resource/delete')?>" onsubmit="return confirm('حذف این مورد قطعی است؟')"><?=csrf_field()?><input type="hidden" name="table" value="<?=e($table)?>"><input type="hidden" name="id" value="<?=e($row['id'])?>"><button class="action-button suspend" type="submit">حذف</button></form><?php endif;?></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td class="empty" colspan="<?= count($columns) ?: 1 ?>">رکوردی برای نمایش وجود ندارد.</td></tr><?php endif; ?></tbody></table></div></div></section>